import {unzipSync} from './vendor/fflate.mjs';
const DB='erosionsector-block-resources';let memory;
function database(){return new Promise((resolve,reject)=>{const r=indexedDB.open(DB,1);r.onupgradeneeded=()=>r.result.createObjectStore('packs');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
export async function savedResources(){if(memory)return memory;try{const db=await database();return await new Promise(resolve=>{const r=db.transaction('packs').objectStore('packs').get('active');r.onsuccess=()=>{db.close();resolve(memory=r.result);};r.onerror=()=>{db.close();resolve(null);};});}catch{return null;}}
export async function importResources(bytes){if(bytes.length>64*1024*1024)throw Error('리소스 묶음은 64MB 이하여야 합니다.');let expanded=0;const files=unzipSync(bytes,{filter:f=>{expanded+=f.originalSize;if(expanded>96*1024*1024)throw Error('압축을 푼 리소스가 너무 큽니다.');return /^(index\.json|models-[a-f0-9]+\.json|atlas-[a-f0-9]+\.png|ct-rules\.json|copycat-states\.json)$/.test(f.name);}}),read=name=>{if(!files[name])throw Error('리소스 파일이 없습니다: '+name);return JSON.parse(new TextDecoder().decode(files[name]));},index=read('index.json');if(index.version!==1||!/^models-[a-f0-9]+\.json$/.test(index.models))throw Error('지원하지 않는 리소스 묶음입니다.');const data=read(index.models);if(data.version!==1||!data.states||!data.models||!data.textures||!Array.isArray(data.pages)||data.pages.length>8)throw Error('블록 모델 형식을 확인하세요.');data.ctRules??=files['ct-rules.json']?read('ct-rules.json'):{};data.copycatDefaults??=files['copycat-states.json']?read('copycat-states.json'):{};const atlases=data.pages.map(name=>{if(!/^atlas-[a-f0-9]+\.png$/.test(name)||!files[name])throw Error('텍스처 묶음이 없습니다.');return new Blob([files[name]],{type:'image/png'});});const pack={data,atlases};const db=await database();await new Promise((resolve,reject)=>{const tx=db.transaction('packs','readwrite');tx.objectStore('packs').put(pack,'active');tx.oncomplete=()=>{db.close();resolve();};tx.onerror=()=>{db.close();reject(tx.error);};});memory=pack;return pack;}
